{"code": "import pytest

import impl


def make_request(subject="alice", roles=None, action="s3:GetObject", resource="docs/reports/q1.pdf"):
    if roles is None:
        roles = ["dev"]
    return {"subject": subject, "roles": roles, "action": action, "resource": resource}


def make_policy(effect="ALLOW", principal="*", action="*", resource="*"):
    return {"effect": effect, "principal": principal, "action": action, "resource": resource}


def test_empty_policies_defaults_to_deny():
    request = make_request()
    assert impl.authorize(request, []) == "DENY"


def test_simple_allow_matches():
    request = make_request(subject="alice", roles=["dev"], action="s3:GetObject", resource="docs/reports/q1.pdf")
    policies = [make_policy(effect="ALLOW", principal="role:dev", action="s3:Get*", resource="docs/reports/*")]
    assert impl.authorize(request, policies) == "ALLOW"


def test_no_matching_policy_defaults_to_deny():
    request = make_request(subject="bob", roles=["guest"], action="s3:PutObject", resource="docs/reports/q1.pdf")
    policies = [make_policy(effect="ALLOW", principal="role:dev", action="s3:Get*", resource="docs/reports/*")]
    assert impl.authorize(request, policies) == "DENY"


def test_deny_overrides_allow_regardless_of_order_and_specificity():
    request = {"subject": "alice", "roles": ["contractor"],
               "action": "s3:GetObject", "resource": "docs/reports/q1.pdf"}
    deny_policy = {"effect": "DENY", "principal": "role:contractor",
                   "action": "*", "resource": "docs/reports/*"}
    allow_policy = {"effect": "ALLOW", "principal": "user:alice",
                    "action": "s3:GetObject", "resource": "docs/reports/q1.pdf"}
    assert impl.authorize(request, [deny_policy, allow_policy]) == "DENY"
    assert impl.authorize(request, [allow_policy, deny_policy]) == "DENY"


def test_wildcard_principal_matches_anyone():
    request = make_request(subject="zed", roles=[])
    policies = [make_policy(effect="ALLOW", principal="*", action="*", resource="*")]
    assert impl.authorize(request, policies) == "ALLOW"


def test_user_principal_is_literal_not_pattern():
    request = make_request(subject="alice", roles=[])
    policies = [make_policy(effect="ALLOW", principal="user:al*", action="*", resource="*")]
    # 'user:al*' is a literal principal named 'al*', not a pattern matching 'alice'
    assert impl.authorize(request, policies) == "DENY"


def test_role_principal_requires_role_in_list():
    request = make_request(subject="carol", roles=["oncall"])
    policies = [make_policy(effect="ALLOW", principal="role:dev", action="*", resource="*")]
    assert impl.authorize(request, policies) == "DENY"


def test_empty_roles_list_never_matches_role_principal():
    request = make_request(subject="dave", roles=[])
    policies = [make_policy(effect="ALLOW", principal="role:dev", action="*", resource="*")]
    assert impl.authorize(request, policies) == "DENY"


def test_trailing_star_matches_prefix_including_bare_prefix():
    request_bucket = make_request(action="s3:GetBucket")
    request_bare = make_request(action="s3:Get")
    policies = [make_policy(effect="ALLOW", principal="*", action="s3:Get*", resource="*")]
    assert impl.authorize(request_bucket, policies) == "ALLOW"
    assert impl.authorize(request_bare, policies) == "ALLOW"


def test_resource_star_does_not_cross_missing_separator():
    # 'docs/reports/*' should not match 'docs/reportsQ1' since there's no slash
    request = make_request(resource="docs/reportsQ1")
    policies = [make_policy(effect="ALLOW", principal="*", action="*", resource="docs/reports/*")]
    assert impl.authorize(request, policies) == "DENY"


def test_star_only_in_middle_is_literal_asterisk():
    request = make_request(action="s3:GetObject")
    policies = [make_policy(effect="ALLOW", principal="*", action="s3:*Object", resource="*")]
    # 's3:*Object' is literal, does not match 's3:GetObject'
    assert impl.authorize(request, policies) == "DENY"

    request_literal = make_request(action="s3:*Object")
    assert impl.authorize(request_literal, policies) == "ALLOW"


def test_matching_is_case_sensitive():
    request = make_request(action="S3:GetObject")
    policies = [make_policy(effect="ALLOW", principal="*", action="s3:GetObject", resource="*")]
    assert impl.authorize(request, policies) == "DENY"


def test_effect_case_sensitivity_in_matching_not_error():
    # A correctly-cased ALLOW combined with case-sensitive effect comparisons
    request = make_request()
    policies = [make_policy(effect="ALLOW", principal="*", action="*", resource="*")]
    assert impl.authorize(request, policies) == "ALLOW"


def test_request_missing_field_raises_value_error():
    request = {"subject": "alice", "roles": ["dev"], "action": "s3:GetObject"}
    with pytest.raises(ValueError):
        impl.authorize(request, [])


def test_request_roles_not_a_list_raises_value_error():
    request = {"subject": "alice", "roles": "dev", "action": "s3:GetObject", "resource": "docs/x"}
    with pytest.raises(ValueError):
        impl.authorize(request, [])


def test_policy_missing_field_raises_value_error():
    request = make_request()
    bad_policy = {"effect": "ALLOW", "principal": "*", "action": "*"}
    with pytest.raises(ValueError):
        impl.authorize(request, [bad_policy])


def test_policy_invalid_effect_raises_value_error_with_message():
    request = make_request()
    bad_policy = make_policy(effect="Allow")
    with pytest.raises(ValueError, match="Allow"):
        impl.authorize(request, [bad_policy])


def test_validation_happens_before_deciding_even_if_earlier_policy_would_settle_it():
    request = make_request(subject="alice", roles=["contractor"],
                            action="s3:GetObject", resource="docs/reports/q1.pdf")
    deny_policy = {"effect": "DENY", "principal": "role:contractor",
                   "action": "*", "resource": "docs/reports/*"}
    bad_policy = {"effect": "PERMIT", "principal": "*", "action": "*", "resource": "*"}
    with pytest.raises(ValueError, match="PERMIT"):
        impl.authorize(request, [deny_policy, bad_policy])


def test_arguments_are_not_mutated():
    request = make_request()
    request_copy = dict(request)
    policies = [make_policy(effect="ALLOW", principal="*", action="*", resource="*")]
    policies_copy = [dict(p) for p in policies]
    impl.authorize(request, policies)
    assert request == request_copy
    assert policies == policies_copy


def test_multiple_allows_with_no_deny_results_in_allow():
    request = make_request(subject="eve", roles=["dev", "oncall"])
    policies = [
        make_policy(effect="ALLOW", principal="role:dev", action="s3:Get*", resource="docs/reports/*"),
        make_policy(effect="ALLOW", principal="role:oncall", action="s3:Get*", resource="docs/reports/*"),
    ]
    assert impl.authorize(request, policies) == "ALLOW"
